insert into public.site_settings (id, studio_statement, intro_enabled, contact_email) values (1, 'Alpha Studios is a small crew of builders making native iOS and macOS apps, web apps and the backends behind them. We like calm interfaces, honest code and shipping things people actually use.', true, 'hello@alphastudios.example') on conflict (id) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, location, open_to, languages, interests, experience, education) values ('aarav-menon', 'Aarav Menon', 'Founder, backend engineering', 'Builds the quiet systems that keep everything else running, and makes the coffee.', 'aarav-menon', '{"github":"https://example.com/aarav/github","linkedin":"https://example.com/aarav/linkedin","instagram":"https://example.com/aarav/instagram"}'::jsonb, '{"version":1,"options":{"head":3,"skin":3,"eyes":0,"brows":3,"nose":1,"mouth":1,"hair":7,"hairColor":1,"facialHair":3,"glasses":0,"glassesColor":0,"earrings":0,"chain":0,"outfit":1,"outfitColor":2}}'::jsonb, 'Root Access', '', '[{"name":"Backend","level":5},{"name":"Postgres","level":5},{"name":"TypeScript","level":4},{"name":"DevOps","level":3}]'::jsonb, '', '', 'Breaking Bad', 'Bengaluru, India', 'Mentoring, backend side projects', array['English', 'Malayalam', 'Hindi']::text[], array['Espresso', 'Chess', 'Trail running']::text[], '[{"title":"Founder and backend engineer","org":"Alpha Studios","from":"2024","to":"Now","note":"Designs the sync and receipts services behind every app."},{"title":"Backend engineer","org":"Northwind Labs","from":"2020","to":"2024","note":"Moved a monolith onto small services without downtime."}]'::jsonb, '[{"school":"Example Institute of Technology","field":"Computer science","from":"2016","to":"2020"}]'::jsonb) on conflict (slug) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, location, open_to, languages, interests, experience, education) values ('zara-okafor', 'Zara Okafor', 'Interface and motion', 'Sweats the easing curves so you never notice the interface at all.', 'zara-okafor', '{"github":"https://example.com/zara/github","linkedin":"https://example.com/zara/linkedin","instagram":"https://example.com/zara/instagram"}'::jsonb, '{"version":1,"options":{"head":2,"skin":6,"eyes":3,"brows":1,"nose":0,"mouth":1,"hair":3,"hairColor":0,"facialHair":0,"glasses":1,"glassesColor":1,"earrings":2,"chain":1,"outfit":2,"outfitColor":7}}'::jsonb, 'Motion Maven', '', '[{"name":"React","level":5},{"name":"Motion","level":5},{"name":"Design","level":4},{"name":"Accessibility","level":4}]'::jsonb, '', '', 'Minecraft', 'Lagos, Nigeria', 'Design reviews, speaking', array['English', 'Yoruba', 'French']::text[], array['Illustration', 'Afrobeats', 'Board games']::text[], '[{"title":"Interface and motion lead","org":"Alpha Studios","from":"2024","to":"Now","note":"Owns the motion language and the design system."},{"title":"Product designer","org":"Brightpath","from":"2021","to":"2024","note":"Shipped an onboarding flow that cut drop-off by a third."}]'::jsonb, '[{"school":"Example University","field":"Industrial design","from":"2017","to":"2021"}]'::jsonb) on conflict (slug) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, location, open_to, languages, interests, experience, education) values ('kenji-watanabe', 'Kenji Watanabe', 'iOS and macOS lead', 'Ships small, sharp native apps and plans three releases ahead.', 'kenji-watanabe', '{"github":"https://example.com/kenji/github","linkedin":"https://example.com/kenji/linkedin","instagram":"https://example.com/kenji/instagram"}'::jsonb, '{"version":1,"options":{"head":1,"skin":1,"eyes":2,"brows":2,"nose":2,"mouth":0,"hair":6,"hairColor":0,"facialHair":0,"glasses":2,"glassesColor":4,"earrings":0,"chain":0,"outfit":0,"outfitColor":4}}'::jsonb, 'The Professor', '', '[{"name":"Swift","level":5},{"name":"SwiftUI","level":5},{"name":"Testing","level":4},{"name":"CloudKit","level":3}]'::jsonb, '', '', 'Money Heist', 'Osaka, Japan', 'Code reviews, mentoring juniors', array['Japanese', 'English']::text[], array['Film cameras', 'Ramen hunting', 'Go']::text[], '[{"title":"iOS and macOS lead","org":"Alpha Studios","from":"2024","to":"Now","note":"Leads the native apps and their release plans."},{"title":"iOS developer","org":"Tidewater Apps","from":"2019","to":"2024","note":"Five apps shipped, two with over a million downloads."}]'::jsonb, '[{"school":"Example Polytechnic","field":"Information engineering","from":"2015","to":"2019"}]'::jsonb) on conflict (slug) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, location, open_to, languages, interests, experience, education) values ('priya-nair', 'Priya Nair', 'Android and platform', 'Keeps builds green, phones happy and her best ideas for after midnight.', 'priya-nair', '{"github":"https://example.com/priya/github","linkedin":"https://example.com/priya/linkedin","instagram":"https://example.com/priya/instagram"}'::jsonb, '{"version":1,"options":{"head":0,"skin":4,"eyes":1,"brows":4,"nose":3,"mouth":4,"hair":4,"hairColor":1,"facialHair":0,"glasses":0,"glassesColor":0,"earrings":1,"chain":0,"outfit":1,"outfitColor":5}}'::jsonb, 'Night Owl', '', '[{"name":"Kotlin","level":5},{"name":"Compose","level":4},{"name":"CI","level":4},{"name":"Firebase","level":3}]'::jsonb, '', '', 'Interstellar', 'Pune, India', 'Android talks, pair programming', array['English', 'Malayalam', 'Marathi']::text[], array['Astronomy', 'Night photography', 'Baking']::text[], '[{"title":"Android and platform engineer","org":"Alpha Studios","from":"2025","to":"Now","note":"Builds the Android apps and keeps the pipelines green."},{"title":"Android developer","org":"Orbit Mobile","from":"2021","to":"2025","note":"Rewrote a legacy app in Compose."}]'::jsonb, '[{"school":"Example College of Engineering","field":"Electronics","from":"2017","to":"2021"}]'::jsonb) on conflict (slug) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, location, open_to, languages, interests, experience, education) values ('mateo-alvarez', 'Mateo Alvarez', 'Product and quality', 'Finds the bug before you do, then buys everyone lunch to say sorry.', 'mateo-alvarez', '{"github":"https://example.com/mateo/github","linkedin":"https://example.com/mateo/linkedin","instagram":"https://example.com/mateo/instagram"}'::jsonb, '{"version":1,"options":{"head":4,"skin":2,"eyes":4,"brows":0,"nose":0,"mouth":3,"hair":5,"hairColor":3,"facialHair":1,"glasses":3,"glassesColor":2,"earrings":0,"chain":2,"outfit":2,"outfitColor":3}}'::jsonb, 'Wildcard', '', '[{"name":"Product","level":5},{"name":"Testing","level":5},{"name":"Research","level":4},{"name":"Docs","level":4}]'::jsonb, '', '', 'GTA VI', 'Mexico City, Mexico', 'User research, testing workshops', array['Spanish', 'English']::text[], array['Street food', 'Retro games', 'Football']::text[], '[{"title":"Product and quality lead","org":"Alpha Studios","from":"2024","to":"Now","note":"Turns rough ideas into clear plans and tests them hard."},{"title":"QA analyst","org":"Pixel Forge","from":"2020","to":"2024","note":"Built the test plan for a game used by half a million players."}]'::jsonb, '[{"school":"Example Autonomous University","field":"Communication","from":"2015","to":"2019"}]'::jsonb) on conflict (slug) do nothing;
insert into public.projects (slug, name, summary, story, status, platforms, tech, links, repo, featured, screenshots) values ('harbor', 'Harbor', 'A calm money app for freelancers: track invoices, set money aside for taxes and see what you can safely spend.', 'Freelancers told us the hardest part of money was not earning it but knowing what was theirs to spend. Harbor sets tax aside the moment an invoice is paid, shows a single safe-to-spend number, and syncs quietly between iPhone and Mac with no accounts to create. We built it native in SwiftUI so it opens instantly and feels at home on both devices. Kenji led the app, Aarav built the sync and receipts service, Zara shaped the interface and Mateo kept it honest in testing.', 'live', array['ios', 'macos']::text[], array['Swift', 'SwiftUI', 'CloudKit', 'StoreKit']::text[], '{"appStore":"https://example.com/harbor/app-store","github":"https://example.com/alpha-studios/harbor"}'::jsonb, 'alpha-studios-demo/harbor', true, '[{"src":"screens/harbor-iphone-1.png","alt":"Harbor home screen showing the safe-to-spend number","device":"iphone"},{"src":"screens/harbor-mac-1.png","alt":"Harbor on Mac with the invoice list open","device":"mac"},{"src":"screens/harbor-iphone-2.png","alt":"Harbor tax pot screen on iPhone","device":"iphone"}]'::jsonb) on conflict (slug) do nothing;
insert into public.projects (slug, name, summary, story, status, platforms, tech, links, repo, featured, screenshots) values ('lumen', 'Lumen', 'A study planner that turns deadlines into small, doable evenings and cheers you on when you finish one.', 'Lumen began as a late-night fix for a friend with four deadlines and no plan. You add what is due, and it breaks the work into short evening sessions you can actually finish, then celebrates each one with a small burst of light. The web app runs on React and Postgres, with an Android companion in Kotlin for reminders. It is in open beta while we listen to students about what to add next. Zara led the web interface, Priya built the Android app, Aarav the backend and Mateo the research.', 'beta', array['web', 'android']::text[], array['React', 'TypeScript', 'Postgres', 'Kotlin']::text[], '{"github":"https://example.com/alpha-studios/lumen","demo":"https://example.com/lumen/demo"}'::jsonb, 'alpha-studios-demo/lumen', true, '[{"src":"screens/lumen-browser-1.png","alt":"Lumen weekly plan in the browser","device":"browser"},{"src":"screens/lumen-android-1.png","alt":"Lumen evening session on Android","device":"android"},{"src":"screens/lumen-browser-2.png","alt":"Lumen progress view in the browser","device":"browser"}]'::jsonb) on conflict (slug) do nothing;
